// Package env resolves a repo's layered .env files for a configuration.
//
// Resolution order for repo api with configuration staging, later wins:
//
//	environments/_shared/base.env
//	environments/_shared/staging.env
//	environments/api/base.env
//	environments/api/staging.env
//	environments/api/*.local.env   (git-ignored, personal overrides)
//	extra variables (neptuno up --set KEY=value)
package env

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// SharedDir is the environments/ subfolder every repo inherits from.
const SharedDir = "_shared"

// Var is one resolved variable and the source it came from.
type Var struct {
	Key, Value, Source string
}

// Provider supplies variables from somewhere other than env files, such as a
// secrets manager. Providers run after the files and before --set values.
type Provider interface {
	Name() string
	Vars(repo, config string) (map[string]string, error)
}

// Resolver merges env files under an environments/ directory.
type Resolver struct {
	// Dir is the environments/ directory.
	Dir string
	// Providers run in order after the env files.
	Providers []Provider
}

// Files returns the env files that apply to repo and config, in the order
// they are merged. Files that do not exist are left out.
func (r Resolver) Files(repo, config string) ([]string, error) {
	var files []string
	for _, dir := range []string{SharedDir, repo} {
		for _, name := range []string{"base.env", config + ".env"} {
			path := filepath.Join(r.Dir, dir, name)
			if _, err := os.Stat(path); err == nil {
				files = append(files, path)
			}
		}
	}
	personal, err := filepath.Glob(filepath.Join(r.Dir, repo, "*.local.env"))
	if err != nil {
		return nil, err
	}
	sort.Strings(personal)
	return append(files, personal...), nil
}

// Resolve merges every layer for repo and config, then applies extra.
// The result is sorted by key.
func (r Resolver) Resolve(repo, config string, extra map[string]string) ([]Var, error) {
	files, err := r.Files(repo, config)
	if err != nil {
		return nil, err
	}
	merged := map[string]Var{}
	for _, path := range files {
		vars, err := ParseFile(path)
		if err != nil {
			return nil, err
		}
		source, _ := filepath.Rel(filepath.Dir(r.Dir), path)
		for _, kv := range vars {
			merged[kv[0]] = Var{Key: kv[0], Value: kv[1], Source: filepath.ToSlash(source)}
		}
	}
	for _, p := range r.Providers {
		vars, err := p.Vars(repo, config)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", p.Name(), err)
		}
		for k, v := range vars {
			merged[k] = Var{Key: k, Value: v, Source: p.Name()}
		}
	}
	for k, v := range extra {
		merged[k] = Var{Key: k, Value: v, Source: "--set"}
	}

	out := make([]Var, 0, len(merged))
	for _, v := range merged {
		out = append(out, v)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Key < out[j].Key })
	return out, nil
}

// ParseFile reads a .env file into ordered key/value pairs.
func ParseFile(path string) ([][2]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	vars, err := Parse(f)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return vars, nil
}

// Parse reads KEY=VALUE lines. It skips blank lines and # comments, accepts
// an optional "export " prefix, and strips matching single or double quotes
// around a value. Unquoted values lose a trailing " # comment".
func Parse(r io.Reader) ([][2]string, error) {
	var vars [][2]string
	sc := bufio.NewScanner(r)
	for n := 1; sc.Scan(); n++ {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		line = strings.TrimPrefix(line, "export ")
		key, value, ok := strings.Cut(line, "=")
		key = strings.TrimSpace(key)
		if !ok || key == "" || strings.ContainsAny(key, " \t") {
			return nil, fmt.Errorf("line %d: expected KEY=VALUE", n)
		}
		value = strings.TrimSpace(value)
		if len(value) >= 2 && value[0] == '\'' && value[len(value)-1] == '\'' {
			value = value[1 : len(value)-1]
		} else if len(value) >= 2 && value[0] == '"' && value[len(value)-1] == '"' {
			value = strings.NewReplacer(`\\`, `\`, `\"`, `"`, `\n`, "\n").Replace(value[1 : len(value)-1])
		} else if i := strings.Index(value, " #"); i >= 0 {
			value = strings.TrimSpace(value[:i])
		}
		vars = append(vars, [2]string{key, value})
	}
	return vars, sc.Err()
}

// Write saves vars as a .env file docker compose can read with env_file.
func Write(path string, vars []Var) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	var b strings.Builder
	b.WriteString("# Generated by neptuno. Edit the files under environments/ instead.\n")
	for _, v := range vars {
		fmt.Fprintf(&b, "%s=%s\n", v.Key, quote(v.Value))
	}
	return os.WriteFile(path, []byte(b.String()), 0o600)
}

// ParseAssignments turns KEY=value strings, as given to --set, into a map.
func ParseAssignments(list []string) (map[string]string, error) {
	out := map[string]string{}
	for _, a := range list {
		k, v, ok := strings.Cut(a, "=")
		if !ok || k == "" {
			return nil, fmt.Errorf("%q: expected KEY=value", a)
		}
		out[k] = v
	}
	return out, nil
}

// quote leaves plain values bare, single-quotes values with spaces or shell
// characters, and double-quotes values that themselves hold a single quote.
func quote(v string) string {
	if v == "" || !strings.ContainsAny(v, " \t\n#'\"$`\\") {
		return v
	}
	if !strings.ContainsAny(v, "'\n") {
		return "'" + v + "'"
	}
	return `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`, "\n", `\n`).Replace(v) + `"`
}

// Configs lists the configurations a repo can switch to: every <name>.env in
// environments/_shared and environments/<repo>, apart from base.env and
// personal *.local.env files, plus always, which is listed first, sorted.
func (r Resolver) Configs(repo string, always ...string) []string {
	seen := map[string]bool{}
	var out []string
	add := func(name string) {
		if name != "" && !seen[name] {
			seen[name] = true
			out = append(out, name)
		}
	}
	for _, name := range always {
		add(name)
	}
	var found []string
	for _, dir := range []string{SharedDir, repo} {
		matches, _ := filepath.Glob(filepath.Join(r.Dir, dir, "*.env"))
		for _, m := range matches {
			name := strings.TrimSuffix(filepath.Base(m), ".env")
			if name != "base" && !strings.HasSuffix(name, ".local") {
				found = append(found, name)
			}
		}
	}
	sort.Strings(found)
	for _, name := range found {
		add(name)
	}
	return out
}
